-- Turtle Fleet 0.3.1 | Generated by tools/build.py; edit src/ instead.
local factories, loaded = {}, {}
local nativeRequire = require
local function require(name)
  if loaded[name] then return loaded[name] end
  if not factories[name] then return nativeRequire(name) end
  loaded[name] = factories[name]()
  return loaded[name]
end
factories["fleet.gui"] = function()
-- Retained focus and editing state over an immediate-mode, cell-based display.
-- Rendering uses term.blit, never print/read, so content cannot scroll the screen.
local M = {}

function M.clean(text)
  return tostring(text or ""):gsub("[%z\1-\31\127-\255]", " ")
end

function M.wrap(text, width)
  local lines, line = {}, ""
  for word in M.clean(text):gmatch("%S+") do
    if #line > 0 and #line + #word + 1 > width then lines[#lines + 1], line = line, "" end
    while #word > width do
      if #line > 0 then lines[#lines + 1], line = line, "" end
      lines[#lines + 1], word = word:sub(1, width), word:sub(width + 1)
    end
    if #word > 0 then line = line == "" and word or line .. " " .. word end
  end
  if #line > 0 then lines[#lines + 1] = line end
  return lines
end

function M.new(display, keys)
  local self = { widgets = {}, focus = nil, cursors = {}, shift = false, ctrl = false, previous = {} }
  local fg, bg

  function self.begin(title, subtitle)
    self.width, self.height = display.getSize()
    self.color = display.isColor()
    self.left = math.floor((self.width - math.min(40, self.width)) / 2) + 1
    self.size = math.min(40, self.width)
    self.rows, self.widgets = {}, {}
    for y = 1, self.height do
      self.rows[y] = { text = string.rep(" ", self.width), fg = string.rep("0", self.width), bg = string.rep("f", self.width) }
    end
    self.fill(1, 1, self.size, 1, self.color and "b" or "0")
    self.text(2, 1, title, self.size - 2, self.color and "0" or "f", self.color and "b" or "0")
    self.text(2, 2, subtitle or "", self.size - 2, "8")
    self.text(2, self.height, "Tab/Arrows Enter Esc", self.size - 2, "8")
  end

  local function splice(value, x, text) return value:sub(1, x - 1) .. text .. value:sub(x + #text) end

  function self.text(x, y, text, width, color, background)
    if y < 1 or y > self.height then return end
    local absolute = x + self.left - 1
    local value = M.clean(text):sub(1, math.max(0, math.min(width or self.size, self.size - x + 1)))
    if absolute < 1 then value, absolute = value:sub(2 - absolute), 1 end
    value = value:sub(1, math.max(0, self.width - absolute + 1))
    if #value == 0 then return end
    local row = self.rows[y]
    color = color or "0"
    if not self.color and color ~= "0" and color ~= "7" and color ~= "8" and color ~= "f" then color = "0" end
    row.text = splice(row.text, absolute, value)
    row.fg = splice(row.fg, absolute, string.rep(color, #value))
    if background then row.bg = splice(row.bg, absolute, string.rep(background, #value)) end
  end

  function self.fill(x, y, width, height, color)
    for row = y, y + height - 1 do self.text(x, row, string.rep(" ", width), width, "0", color) end
  end

  function self.paragraph(y, text, count, color)
    for i, line in ipairs(M.wrap(text, self.size - 4)) do
      if i > count then break end
      self.text(3, y + i - 1, line, self.size - 4, color)
    end
  end

  function self.button(id, label, x, y, width, action, options)
    options = options or {}
    self.widgets[#self.widgets + 1] = {
      id = id, label = label, x = x, y = y, width = width, height = options.height or 2,
      action = action or id, enabled = options.enabled ~= false, danger = options.danger,
      sub = options.sub, primary=options.primary, kind = "button",
    }
  end

  function self.field(id, label, y, value, change, options)
    options = options or {}
    self.text(3, y, label, self.size - 4, "8")
    self.widgets[#self.widgets + 1] = {
      id = id, x = 3, y = y + 1, width = self.size - 4, height = 2,
      value = value, change = change, numeric = options.numeric, max = options.max or 12,
      enabled = true, kind = "field", enter = options.enter,
    }
  end

  function self.footer(backLabel, nextLabel, nextAction, enabled, danger)
    local half = math.floor((self.size - 5) / 2)
    self.button("back", backLabel or "Back", 2, self.height - 2, half, "back")
    if nextLabel then
      self.button("next", nextLabel, 4 + half, self.height - 2, self.size - half - 4,
        nextAction or "next", { enabled = enabled, danger = danger })
    end
  end

  function self.progress(y, done, total)
    local width = self.size - 4
    local filled = total > 0 and math.floor(math.min(1, done / total) * width) or 0
    self.text(3, y, string.rep("#", filled) .. string.rep("-", width - filled), width, self.color and "5" or "0")
  end

  function self.find(id)
    for i, widget in ipairs(self.widgets) do if widget.id == id then return widget, i end end
  end

  function self.moveFocus(amount)
    local _, current = self.find(self.focus)
    current = current or (amount > 0 and 0 or 1)
    for _ = 1, #self.widgets do
      current = (current - 1 + amount) % #self.widgets + 1
      if self.widgets[current].enabled then self.focus = self.widgets[current].id; return end
    end
    self.focus = nil
  end

  function self.finish()
    local focus = self.find(self.focus)
    if not focus or not focus.enabled then self.moveFocus(1) end
    self.cursor = nil
    for _, w in ipairs(self.widgets) do
      local selected = self.focus == w.id
      bg = not w.enabled and "f" or selected and (self.color and "b" or "0") or "7"
      fg = not w.enabled and "8" or selected and not self.color and "f" or "0"
      if w.danger and w.enabled and self.color and not selected then bg = "e" end
      if w.primary and w.enabled and self.color then bg="b" end
      self.fill(w.x, w.y, w.width, w.height, bg)
      if w.kind == "field" then
        local cursor = math.min(self.cursors[w.id] or #w.value, #w.value)
        self.cursors[w.id] = cursor
        local offset = math.max(0, cursor - (w.width - 3))
        self.text(w.x, w.y, selected and ">" or " ", 1, fg, bg)
        self.text(w.x + 1, w.y, w.value:sub(offset + 1), w.width - 2, fg, bg)
        if selected then self.cursor = { x = self.left + w.x + cursor - offset, y = w.y } end
      else
        self.text(w.x, w.y, selected and ">" or " ", 1, fg, bg)
        self.text(w.x + 1, w.y, w.label, w.width - 2, fg, bg)
        if w.sub then self.text(w.x + 1, w.y + 1, w.sub, w.width - 2, fg, bg) end
      end
    end
    display.setCursorBlink(false)
    for y, row in ipairs(self.rows) do
      local signature = row.text .. row.fg .. row.bg
      if self.previous[y] ~= signature then
        display.setCursorPos(1, y)
        display.blit(row.text, row.fg, row.bg)
        self.previous[y] = signature
      end
    end
    for y = self.height + 1, #self.previous do self.previous[y] = nil end
    if self.cursor then display.setCursorPos(self.cursor.x, self.cursor.y); display.setCursorBlink(true) end
  end

  local function insert(w, text)
    text = M.clean(text)
    local pos = self.cursors[w.id] or #w.value
    local updated = w.value:sub(1, pos) .. text .. w.value:sub(pos + 1)
    if #updated > w.max or (w.numeric and not updated:match("^%-?%d*$")) then return end
    w.change(updated)
    self.cursors[w.id] = pos + #text
  end

  function self.event(event, a, b, c)
    local w = self.find(self.focus)
    if event == "term_resize" then self.previous = {}; return end
    if event == "key_up" then
      if a == keys.leftShift or a == keys.rightShift then self.shift = false end
      if a == keys.leftCtrl or a == keys.rightCtrl then self.ctrl = false end
    elseif event == "mouse_click" and a == 1 and self.color then
      local x = b - self.left + 1
      for _, widget in ipairs(self.widgets) do
        if widget.enabled and x >= widget.x and x < widget.x + widget.width
          and c >= widget.y and c < widget.y + widget.height then
          self.focus = widget.id
          if widget.kind == "button" then return widget.action end
          local old = self.cursors[widget.id] or #widget.value
          local offset = math.max(0, old - (widget.width - 3))
          self.cursors[widget.id] = math.max(0, math.min(#widget.value, x - widget.x - 1 + offset))
          return
        end
      end
    elseif event == "key" then
      if b == true and (a == keys.enter or a == keys.numPadEnter or a == keys.space) then return end
      if a == keys.leftShift or a == keys.rightShift then self.shift = true; return end
      if a == keys.leftCtrl or a == keys.rightCtrl then self.ctrl = true; return end
      if a == keys.escape then return "back" end
      if a == keys.tab then self.moveFocus(self.shift and -1 or 1); return end
      if a == keys.up or a == keys.down then self.moveFocus(a == keys.up and -1 or 1); return end
      if w and w.kind == "field" then
        local pos = self.cursors[w.id] or #w.value
        if a == keys.left then self.cursors[w.id] = math.max(0, pos - 1)
        elseif a == keys.right then self.cursors[w.id] = math.min(#w.value, pos + 1)
        elseif a == keys.home then self.cursors[w.id] = 0
        elseif a == keys["end"] then self.cursors[w.id] = #w.value
        elseif a == keys.backspace and pos > 0 then
          w.change(w.value:sub(1, pos - 1) .. w.value:sub(pos + 1)); self.cursors[w.id] = pos - 1
        elseif a == keys.delete then w.change(w.value:sub(1, pos) .. w.value:sub(pos + 2))
        elseif a == keys.u and self.ctrl then w.change(""); self.cursors[w.id] = 0
        elseif a == keys.enter or a == keys.numPadEnter then self.focus = w.enter or "next" end
      elseif a == keys.left or a == keys.right then self.moveFocus(a == keys.left and -1 or 1)
      elseif (a == keys.enter or a == keys.numPadEnter or a == keys.space) and w and w.enabled then return w.action end
    elseif (event == "char" or event == "paste") and w and w.kind == "field" and not self.ctrl then insert(w, a)
    end
  end
  return self
end

return M

end
factories["fleet.install_core"] = function()
-- Filesystem work is separated from the installer GUI for failure-path testing.
local M = {}
M.DESTINATION = "/fleet.lua"
M.STARTUP = "/startup/fleet.lua"
M.LAUNCHER = '-- Turtle Fleet startup launcher\nshell.run("/fleet.lua")\n'

local function readFile(fs, path)
  if not fs.exists(path) then return nil end
  if fs.isDir(path) then error(path .. " is a directory.", 0) end
  local handle, why = fs.open(path, "r")
  if not handle then error(why or "Cannot read " .. path, 0) end
  local ok, value = pcall(handle.readAll)
  handle.close()
  if not ok then error(value, 0) end
  return value
end

function M.managedLauncher(source)
  if not source then return false end
  source = source:gsub("\r\n", "\n")
  return source == M.LAUNCHER or source:match('^%s*shell%.run%("/fleet%.lua"%)%s*$') ~= nil
    or source:match("^%s*shell%.run%('/fleet%.lua'%)%s*$") ~= nil
end

local function unused(fs, base)
  if not fs.exists(base) then return base end
  for i = 1, 999 do
    local path = base .. "." .. i
    if not fs.exists(path) then return path end
  end
  error("Too many installer backup files. Move older backups elsewhere.", 0)
end

function M.inspect(fs)
  local ok, result = pcall(function()
    local info = { startupAvailable = true, existing = fs.exists(M.DESTINATION) }
    if fs.exists("/startup") and not fs.isDir("/startup") then
      info.startupAvailable, info.note = false, "An existing /startup file is kept. Use manual launch."
    elseif fs.exists(M.STARTUP) and (fs.isDir(M.STARTUP) or not M.managedLauncher(readFile(fs, M.STARTUP))) then
      info.startupAvailable, info.note = false, "Your custom /startup/fleet.lua is kept. Manage startup there."
    elseif fs.exists("/startup.lua") then
      info.note = "Your /startup.lua is kept. Avoid adding a second Fleet launcher."
    end
    info.managedStartup = info.startupAvailable and fs.exists(M.STARTUP)
    return info
  end)
  if ok then return result end
  return nil, tostring(result)
end

function M.prepare(fs, payloads, role, startup, isTurtle)
  local ok, result = pcall(function()
    if role ~= "controller" and role ~= "worker" then error("Choose Controller or Turtle Worker.", 0) end
    if role == "worker" and not isTurtle then error("The worker can only be installed on a turtle.", 0) end
    local source = payloads[role]
    if type(source) ~= "string" or #source == 0 then error("Installer is missing the selected program.", 0) end
    local compiled, why = load(source, "@fleet.lua", "t", {})
    if not compiled then error("Bundled program is invalid: " .. tostring(why), 0) end
    local info, problem = M.inspect(fs)
    if not info then error(problem, 0) end
    if startup and not info.startupAvailable then error(info.note, 0) end
    if fs.isReadOnly("/") or fs.isReadOnly(M.DESTINATION) then error("Computer storage is read-only.", 0) end
    local original = readFile(fs, M.DESTINATION)
    local oldStartup = fs.exists("/startup") and fs.isDir("/startup") and not fs.isDir(M.STARTUP)
      and readFile(fs, M.STARTUP) or nil
    local changeStartup = startup and oldStartup ~= M.LAUNCHER or not startup and M.managedLauncher(oldStartup)
    if changeStartup and (fs.isReadOnly("/startup") or fs.isReadOnly(M.STARTUP)) then error("Startup storage is read-only.", 0) end
    local free = fs.getFreeSpace("/")
    if type(free) == "number" and free < #source + #M.LAUNCHER + 1024 then error("Not enough free space to install safely.", 0) end
    return { role = role, source = source, original = original, startup = startup,
      oldStartup = oldStartup, changeStartup = changeStartup, info = info,
      backup = original and unused(fs, M.DESTINATION .. ".backup") or nil }
  end)
  if ok then return result end
  return nil, tostring(result)
end

local function writeVerified(fs, path, source)
  local handle, why = fs.open(path, "w")
  if not handle then error(why or "Cannot write " .. path, 0) end
  local ok, problem = pcall(function() handle.write(source); handle.close() end)
  if not ok then pcall(handle.close); error(problem, 0) end
  if readFile(fs, path) ~= source then error("Written file could not be verified: " .. path, 0) end
end

function M.apply(fs, plan)
  local staged, stagedStartup, savedStartup
  local movedOriginal, installed, movedStartup, installedStartup, madeDirectory = false, false, false, false, false
  local ok, why = pcall(function()
    -- The review must still describe the files we are about to change.
    if readFile(fs, M.DESTINATION) ~= plan.original then error("Installed program changed. Review the installation again.", 0) end
    local info, problem = M.inspect(fs)
    if not info then error(problem, 0) end
    if plan.startup and not info.startupAvailable then error(info.note, 0) end
    if plan.changeStartup then
      if fs.exists("/startup") and not fs.isDir("/startup") then error("Startup changed. Review again.", 0) end
      if readFile(fs, M.STARTUP) ~= plan.oldStartup then error("Startup changed. Review again.", 0) end
    end
    if plan.backup and fs.exists(plan.backup) then error("Backup path changed. Review again.", 0) end
    staged = unused(fs, "/.fleet-install.tmp")
    writeVerified(fs, staged, plan.source)
    if plan.changeStartup and plan.startup then
      stagedStartup = unused(fs, "/.fleet-startup.tmp")
      writeVerified(fs, stagedStartup, M.LAUNCHER)
    end
    if plan.backup then fs.move(M.DESTINATION, plan.backup); movedOriginal = true end
    fs.move(staged, M.DESTINATION); staged, installed = nil, true
    if plan.changeStartup then
      if not fs.exists("/startup") then fs.makeDir("/startup"); madeDirectory = true end
      if plan.oldStartup then
        savedStartup = unused(fs, "/.fleet-startup.backup")
        fs.move(M.STARTUP, savedStartup); movedStartup = true
      end
      if plan.startup then
        fs.move(stagedStartup, M.STARTUP); stagedStartup, installedStartup = nil, true
      end
    end
  end)
  local cleanupWarnings = {}
  local function attempt(action, description)
    local success, failure = pcall(action)
    if not success then cleanupWarnings[#cleanupWarnings + 1] = description .. ": " .. tostring(failure) end
  end
  if not ok then
    -- Restore old files if a filesystem operation fails after installation starts.
    if installedStartup then attempt(function() fs.delete(M.STARTUP) end, "Remove new startup launcher") end
    if movedStartup then attempt(function() fs.move(savedStartup, M.STARTUP) end, "Restore startup from " .. savedStartup) end
    if installed then attempt(function() fs.delete(M.DESTINATION) end, "Remove new program") end
    if movedOriginal then attempt(function() fs.move(plan.backup, M.DESTINATION) end, "Restore program from " .. plan.backup) end
    if madeDirectory then
      attempt(function() if #fs.list("/startup") == 0 then fs.delete("/startup") end end, "Remove empty startup directory")
    end
  elseif savedStartup then
    attempt(function() fs.delete(savedStartup) end, "Remove temporary startup backup")
  end
  for _, path in ipairs({ staged or false, stagedStartup or false }) do
    if path and fs.exists(path) then attempt(function() fs.delete(path) end, "Remove staging file " .. path) end
  end
  if not ok then
    return nil, tostring(why) .. (#cleanupWarnings > 0 and (" Recovery needed: " .. table.concat(cleanupWarnings, "; ")) or " Existing files restored.")
  end
  return { role = plan.role, backup = plan.backup, startup = plan.startup, note = plan.info.note,
    warnings = table.concat(cleanupWarnings, "; ") }
end

return M

end
factories["fleet.installer"] = function()
local gui = require("fleet.gui")
local core = require("fleet.install_core")
local M = {}

function M.new(display, keys, options)
  local g = gui.new(display, keys)
  local fs, payloads = options.fs, options.payloads
  local self = { gui = g, page = options.role and "options" or "role", role = options.role or
    (options.isTurtle and "worker" or "controller"), startup = options.startup ~= false, running = true }
  local function go(page)
    self.page, g.focus = page, nil
    if page == "role" then g.focus = self.role end
  end
  local function message(title, text, back)
    self.messageTitle, self.messageText, self.messagePage, self.messageBack = title, text, 1, back
    go("message")
  end
  local function inspect()
    local info, why = core.inspect(fs)
    if not info then message("INSTALLER ERROR", why, "role"); return end
    self.info = info
    if not info.startupAvailable then self.startup = false end
  end
  inspect()
  if self.page == "role" then g.focus = self.role end

  function self.render()
    local width, height = display.getSize()
    local compact = height < 19
    self.tooSmall = width < 26 or height < 13
    if self.tooSmall then
      g.begin("FLEET INSTALLER", "Display too small")
      g.paragraph(4, "Use at least 26 columns and 13 rows. Esc exits.", math.max(1, height - 6)); g.finish(); return
    end
    local name = self.role == "worker" and "Turtle Worker" or "Controller"
    if self.page == "role" then
      g.begin("FLEET INSTALLER", "Choose what to install")
      g.button("controller", "Controller", 2, compact and 4 or 5, g.size - 2, "controller", { height = compact and 2 or 3,
        sub = options.isTurtle and "Control a turtle fleet" or "Recommended here" })
      g.button("worker", "Turtle Worker", 2, compact and 7 or 10, g.size - 2, "worker", { height = compact and 2 or 3, enabled = options.isTurtle,
        sub = options.isTurtle and "Recommended here" or "Requires a turtle" })
      g.paragraph(compact and 9 or 15, "Both programs included.", 1, "8")
      g.footer("Quit")
    elseif self.page == "options" then
      g.begin("INSTALL OPTIONS", name)
      g.paragraph(4, self.role == "worker" and "Needs a pickaxe and a wireless modem to work." or
        "Use a wireless modem to discover your turtles.", 3)
      g.button("startup", self.startup and "[x] Start on boot" or "[ ] Start on boot", 2, compact and 7 or 8, g.size - 2,
        "startup", { height = compact and 1 or 2, enabled = self.info and self.info.startupAvailable })
      if compact then
        g.button("setupDetails", self.info and self.info.note and "Startup notice" or "Setup details",
          2, 9, g.size - 2, "setupDetails", { height = 1 })
      else
        g.paragraph(12, self.info and self.info.note or "Fleet settings are kept. An existing program will be backed up.", 5, "8")
      end
      g.footer("Back", "Next")
    elseif self.page == "review" then
      g.begin("READY TO INSTALL", name)
      g.text(3, 4, "Program: /fleet.lua", g.size - 4)
      g.text(3, compact and 5 or 6, self.startup and "Startup: enabled" or "Startup: manual", g.size - 4, "5")
      if compact then
        g.paragraph(7, self.plan.backup and "Existing program will be backed up." or "A new program will be installed.", 2)
        g.paragraph(9, "Settings and other programs kept.", 2, "8")
      else
        g.paragraph(8, self.plan.backup and "An existing /fleet.lua will be backed up before replacing it." or
          "A new /fleet.lua will be installed.", 4)
        g.paragraph(13, "Existing fleet settings and other programs stay in place.", 3, "8")
      end
      g.footer("Back", "Install", "install")
    elseif self.page == "installing" then
      g.begin("INSTALLING", name)
      g.paragraph(5, "Writing and verifying the selected program...", 4)
    elseif self.page == "done" then
      g.begin("INSTALL COMPLETE", name)
      g.text(3, 4, "Run: fleet", g.size - 4, "5")
      g.text(3, compact and 5 or 6, self.result.startup and "Starts on boot." or "Launch manually.", g.size - 4)
      g.paragraph(compact and 7 or 8, compact and "Launch to set up your fleet." or
        "Launch now to configure the fleet name and connect your turtles.", compact and 2 or 4)
      g.button("details", "Install details", 2, compact and 9 or 13, g.size - 2, "details", { height = compact and 1 or 2 })
      g.footer("Done", "Launch", "launch")
    elseif self.page == "message" then
      g.begin(self.messageTitle, "Turtle Fleet installer")
      local lines = gui.wrap(self.messageText, g.size - 4)
      local per = height - 8
      local pages = math.max(1, math.ceil(#lines / per))
      self.messagePage = math.min(self.messagePage, pages)
      for i = (self.messagePage - 1) * per + 1, math.min(#lines, self.messagePage * per) do
        g.text(3, 4 + (i - 1) % per, lines[i], g.size - 4)
      end
      g.text(3, height - 4, "Page " .. self.messagePage .. "/" .. pages, g.size - 4, "8")
      g.footer("Back", self.messagePage < pages and "More" or nil, "more")
    end
    g.finish()
  end

  function self.event(event, a, b, c)
    if event == "term_resize" then g.previous = {} end
    if self.tooSmall then if event == "key" and a == keys.escape then self.running = false end; return end
    local action = g.event(event, a, b, c)
    if action == "back" then
      if self.page == "role" or self.page == "done" then self.running = false
      elseif self.page == "options" then go("role")
      elseif self.page == "review" then go("options"); inspect()
      elseif self.page == "message" then go(self.messageBack) end
    elseif action == "controller" or action == "worker" then self.role = action; go("options"); inspect()
    elseif action == "startup" then self.startup = not self.startup
    elseif action == "setupDetails" then
      message("SETUP DETAILS", ((self.info and self.info.note) or "") ..
        " Fleet settings are kept. An existing /fleet.lua will be backed up. Start on boot adds the Fleet startup launcher; otherwise run fleet manually.", "options")
    elseif action == "next" then
      local plan, why = core.prepare(fs, payloads, self.role, self.startup, options.isTurtle)
      if plan then self.plan = plan; go("review") else message("CANNOT INSTALL", why, "options") end
    elseif action == "install" then
