function M.manifest(m)
  local valid=type(m)=="table" and m.format==1 and m.product=="orbit-os" and M.version(m.version)~=nil
    and m.artifact=="orbit.lua" and type(m.size)=="number" and m.size%1==0 and m.size>0 and m.size<=M.LIMIT
    and type(m.sha256)=="string" and #m.sha256==64 and not m.sha256:find("[^0-9a-f]")
  if not valid then return false end
  -- Older manifests did not list the apps already contained in orbit.lua.
  if m.apps==nil then return true end
  if type(m.apps)~="table" or #m.apps>32 then return false end
  local seen,count={},0
  for index,app in pairs(m.apps) do
    count=count+1
    if type(index)~="number" or index%1~=0 or index<1 or index>#m.apps or type(app)~="table"
      or type(app.id)~="string" or #app.id>32 or not app.id:match("^[%w_-]+$") or seen[app.id]
      or type(app.title)~="string" or #app.title<1 or #app.title>48 or app.title:find("[%c]")
      or not M.version(app.version) then return false end
    seen[app.id]=true
  end
  return count==#m.apps
end
function M.verify(m,source,yield)
  assert(M.manifest(m),"Invalid Orbit release manifest")
  assert(type(source)=="string" and #source==m.size,"Release size does not match manifest")
  assert(sha.digest(source,yield)==m.sha256,"Release checksum does not match; nothing installed")
  assert(load(source,"@orbit.lua","t",{}),"Release is not valid Lua")
  return true
end
function M.read(fs,path,limit)
  if fs.getSize then assert(fs.getSize(path)<=limit,"File exceeds size limit") end
  local f=assert(fs.open(path,"r"),"Cannot read "..path)
  local ok,value=pcall(f.readAll); f.close(); assert(ok,value)
  assert(type(value)=="string" and #value<=limit,"File exceeds size limit"); return value
end
function M.fetch(base,name,fs,http)
  base=base:gsub("/manifest%.json$",""):gsub("/+$","")
  if base:match("^https://") then
    assert(http and http.get,"HTTP is disabled on this computer")
    base=base:gsub("^https://github.com/([^/]+/[^/]+)/blob/","https://raw.githubusercontent.com/%1/")
    local f,why,failed=http.get({url=base.."/"..name,binary=true,timeout=15})
    if not f then if failed then failed.close() end; error(why or "Download failed",0) end
    local limit=(name=="manifest.json" or name=="worker.json") and 16384 or M.LIMIT
    local ok,value=pcall(function()
      local parts,total={},0
      while true do local chunk=f.read(math.min(8192,limit-total+1)); if not chunk then break end; total=total+#chunk; assert(total<=limit,"Download exceeds size limit"); parts[#parts+1]=chunk end
      return table.concat(parts)
    end)
    f.close(); assert(ok,value); return value
  end
  assert(not base:find("://",1,true),"Use an HTTPS release URL or an in-game directory")
  return M.read(fs,base.."/"..name,(name=="manifest.json" or name=="worker.json") and 16384 or M.LIMIT)
end
function M.check(base,current,fs,http,decode,yield)
  assert(type(base)=="string" and #base>0,"Choose an update directory or HTTPS URL")
  local manifest=decode(M.fetch(base,"manifest.json",fs,http))
  assert(M.manifest(manifest),"This directory does not contain an Orbit release")
  assert(M.version(manifest.version)>=assert(M.version(current)),"Older release; use Rollback for the previous installation")
  local source=M.fetch(base,manifest.artifact,fs,http); M.verify(manifest,source,yield)
  local same=fs.exists(M.TARGET) and not fs.isDir(M.TARGET) and M.read(fs,M.TARGET,M.LIMIT)==source
  return {manifest=manifest,source=source,base=base,unchanged=same}
end
local function unused(fs,path)
  if not fs.exists(path) then return path end
  for i=1,999 do if not fs.exists(path.."."..i) then return path.."."..i end end
  error("Move older backups off this computer",0)
end
function M.replace(fs,path,source,backupBase,stageBase)
  assert(not fs.isReadOnly(path),"Installation storage is read-only")
  assert(not fs.exists(path) or not fs.isDir(path),"Destination is a directory")
  local free=fs.getFreeSpace(path)
  assert(type(free)~="number" or free>=#source+1024,"Not enough space for a verified update")
  local backup=fs.exists(path) and unused(fs,backupBase or path..".backup") or nil
  local stage=unused(fs,stageBase or path..".staging")
  local moved=false
  local ok,why=pcall(function()
    local h=assert(fs.open(stage,"w"),"Cannot stage update")
    local written,problem=pcall(h.write,source); h.close(); assert(written,problem)
    assert(M.read(fs,stage,M.LIMIT)==source,"Staged update could not be verified")
    if backup then fs.move(path,backup); moved=true end
    fs.move(stage,path)
  end)
  if not ok then
    if moved then
      local restored,problem=pcall(fs.move,backup,path)
      if not restored then why=tostring(why).." Restore manually from "..backup..": "..tostring(problem) end
    end
    if fs.exists(stage) then pcall(fs.delete,stage) end
    error(why,0)
  end
  return backup
end
function M.retire(fs,path,backupBase)
  if not fs.exists(path) then return end
  local backup=unused(fs,backupBase); fs.move(path,backup); return backup
end
function M.apply(fs,release,yield)
  M.verify(release.manifest,release.source,yield)
  return M.replace(fs,M.TARGET,release.source)
end
function M.rollback(fs,path)
  assert(type(path)=="string" and path:match("^/orbit%.lua%.backup%.?%d*$"),"No managed rollback copy")
  local source=M.read(fs,path,M.LIMIT); assert(load(source,"@orbit.lua","t",{}),"Rollback copy is invalid")
  return M.replace(fs,M.TARGET,source)
end
return M

end
local net = require("fleet.net")
local engine = require("fleet.engine")
local ui = require("fleet.ui")
local updates = require("fleet.updates")
local release = require("fleet.release")
local program = shell and shell.getRunningProgram and shell.getRunningProgram() or "/fleet.lua"
if shell and shell.resolve then program=shell.resolve(program) end
if program:sub(1,1)~="/" then program="/"..program end
local args = { ... }
assert(turtle, "Run the worker on a turtle.")
net.open()
local configPath, markPath = "/.fleet-worker", "/.fleet-interrupted"
local config = ui.load(configPath)
if type(config) ~= "table" or type(config.group) ~= "string" or type(config.owner) ~= "number" or args[1] == "setup" then
  ui.header("Turtle Fleet setup")
  print("Run the controller first to see its ID.")
  config = { group = ui.group(), owner = ui.number("Controller computer ID", nil, 0, 2147483647) }
  ui.save(configPath, config)
end
if not os.getComputerLabel() then os.setComputerLabel("Fleet turtle " .. os.getComputerID()) end

local function mining()
  for _, get in ipairs({ turtle.getEquippedLeft, turtle.getEquippedRight }) do
    local item = get()
    if item and item.name == "minecraft:diamond_pickaxe" then return true end
  end
  return false
end

local worker,updater
local function announce(status, id)
  status = status or worker.snapshot()
  if updater then status.update=updater.status() end
  if id then net.send(id, config.group, "status", status)
  else net.broadcast(config.group, "status", status) end
end

-- A new session invalidates every command sent before a restart.
local session = tostring(os.getComputerID()) .. ":" .. tostring(os.epoch("utc"))
worker = engine.new({
  turtle = turtle, mining = mining, owner = config.owner, label = os.getComputerLabel(),
  now = os.clock, sleep = sleep, session = session, locate = function() return gps.locate(3) end,
  maintenance = function() return updater and updater.busy() end,
  publish = function(status) announce(status) end,
  mark = function(value) ui.save(markPath, value) end,
  clearMark = function() if fs.exists(markPath) then fs.delete(markPath) end end,
})
updater=updates.receiver({owner=config.owner,group=config.group,session=session,version=release.version,
  now=os.clock,active=function() return worker.active end,fs=fs,path=program,yield=function() sleep(0) end})
if fs.exists(markPath) then
  worker.state, worker.reason = "restarted", "Interrupted job discarded. Verify position and submit a new job."
end

local function receiver()
  while true do
    local sender, message, protocol = rednet.receive()
    if protocol==updates.PROTOCOL then
      local reply=updater.receive(sender,message)
      if reply then rednet.send(sender,reply,updates.PROTOCOL) end
      if updater.restart then announce(); sleep(0.2); return end
    elseif protocol==net.PROTOCOL and net.valid(message, config.group) then
      if message.kind == "discover" then announce(worker.snapshot(), sender)
      else
        local reply = worker.handle(sender, message)
        if reply then net.send(sender, config.group, "ack", reply) end
      end
    end
  end
end

local function runner()
  while true do
    updater.tick()
    if not worker.runPending() then sleep(0.1) end
  end
end

local function display()
  while true do
    local s = worker.snapshot()
    announce(s)
    ui.header(os.getComputerLabel())
    print("ID " .. os.getComputerID() .. " | " .. config.group)
    print("Controller: " .. config.owner)
    print("Fleet "..release.version.." | " .. s.state)
    print("Cells: " .. s.done .. "/" .. s.total)
    print("Blocks dug: " .. s.dug)
    print("Fuel: " .. s.fuel .. " (slot 16)")
    if s.pose then print(("At: %d %d %d"):format(s.pose.x, s.pose.y, s.pose.z)) end
    if not s.mining then print("Equip a diamond pickaxe.") end
    print(updater.busy() and updater.state or s.reason)
    print("Ctrl+T: stop worker")
    sleep(2)
  end
end

-- Termination intentionally propagates. A restart never resumes physical work.
parallel.waitForAny(receiver, runner, display)
if updater.restart then return assert(loadfile(program,"t",_ENV))() end
]]
}

end
-- Development entry point. Copy the generated root install.lua into Minecraft.
local bundled, payloads = pcall(function() return require("fleet.payloads") end)
if not bundled then
  error("This is installer source. Copy install.lua from the project root or dist/ into your computer, then run install. Both programs are embedded in that file.", 0)
end
local installer = require("fleet.installer")
local args = { ... }
local role = args[1]
if role == "turtle" then role = "worker" end
if role == "auto" then role = turtle and "worker" or "controller" end
assert(not role or role == "controller" or role == "worker", "Usage: install [auto|controller|worker] [startup|manual]")
assert(not args[2] or args[2] == "startup" or args[2] == "manual", "Choose startup or manual.")
local app = installer.new(term, keys, { fs = fs, payloads = payloads, isTurtle = turtle ~= nil,
  role = role, startup = args[2] ~= "manual" })
local ok, why = pcall(function()
  while app.running do
    app.render()
    app.event(os.pullEvent())
  end
end)
term.setCursorBlink(false)
term.setBackgroundColor(colors.black)
term.setTextColor(colors.white)
term.clear()
term.setCursorPos(1, 1)
if not ok then error(why, 0) end
if app.launch then shell.run("/fleet.lua")
elseif app.result then print("Fleet installed. Run: fleet")
else print("Installer closed.") end
